-- The five synced tables.
--
-- Ownership is per user. NetworthApp keys its rows on a shared `household_id`
-- because two people keep one set of accounts between them; nobody has asked
-- to share a car, so this is `user_id` and the whole households / invites /
-- is_household_member apparatus is not here. Should sharing ever be wanted,
-- the client barely changes — but every policy below has to be rewritten.
--
-- Ids are generated by the app (uuid) so rows can be created offline and
-- pushed later. Deletions are soft (`deleted_at`) so the other phone learns
-- about them on its next sync.
--
-- Two different "deleted" live here on purpose:
--   * `trashed_at` is the app's Trash — the user can still see and restore it,
--     so it travels as an ordinary field and shows up on both phones.
--   * `deleted_at` is the sync's tombstone — the row is gone for good and this
--     is only the note telling the other devices so.
-- NetworthApp has one column because it has no Trash; Caribou has one and it
-- would be wrong to make emptying the bin and syncing a deletion the same act.
--
-- Every time the app knows is stored as epoch milliseconds in a bigint, not as
-- a timestamptz. The sync compares a hash of what it sent against a hash of
-- what comes back, so a value that can be spelled two ways — and a timestamp
-- can: `+00:00` or `Z`, with or without trailing zeros — would look changed on
-- every single pass and re-upload itself forever. An integer has one spelling.

-- ── cars ─────────────────────────────────────────────────────────────────
create table public.cars (
    id                             uuid primary key default gen_random_uuid(),
    user_id                        uuid not null default auth.uid()
                                       references auth.users(id) on delete cascade,
    name                           text not null check (length(trim(name)) between 1 and 100),
    license_plate                  text not null default '' check (length(license_plate) <= 32),
    initial_odometer               numeric(14,2) not null default 0,
    current_odometer               numeric(14,2) not null default 0,
    is_default                     boolean not null default false,
    insurance_expiration_date      bigint,
    kteo_expiration_date           bigint,
    emissions_card_expiration_date bigint,
    road_tax_amount                numeric(14,2),
    road_tax_due_date              bigint,
    last_service_date              bigint,
    last_tire_change_date          bigint,
    tire_brand                     text check (length(tire_brand) <= 100),
    tire_dimensions                text check (length(tire_dimensions) <= 100),
    tire_installation_date         bigint,
    tyre_size                      text check (length(tyre_size) <= 100),
    license_expiration             text check (length(license_expiration) <= 100),
    created_at                     bigint not null default 0,
    updated_at                     bigint not null default 0,
    trashed_at                     bigint,
    deleted_at                     timestamptz,
    -- The target of the child tables' composite foreign keys below, which is
    -- what makes a refill pointing at another user's car impossible by
    -- structure rather than merely forbidden by policy.
    unique (id, user_id)
);

-- ── trips ────────────────────────────────────────────────────────────────
create table public.trips (
    id          uuid primary key default gen_random_uuid(),
    user_id     uuid not null default auth.uid()
                    references auth.users(id) on delete cascade,
    car_id      uuid not null,
    name        text not null default '' check (length(name) <= 100),
    description text check (length(description) <= 500),
    created_at  bigint not null default 0,
    updated_at  bigint not null default 0,
    trashed_at  bigint,
    deleted_at  timestamptz,
    unique (id, user_id),
    foreign key (car_id, user_id) references public.cars(id, user_id) on delete cascade
);

-- ── fuel_refills ─────────────────────────────────────────────────────────
create table public.fuel_refills (
    id               uuid primary key default gen_random_uuid(),
    user_id          uuid not null default auth.uid()
                         references auth.users(id) on delete cascade,
    car_id           uuid not null,
    trip_id          uuid,
    amount_paid      numeric(14,2) not null default 0,
    liters_added     numeric(12,3) not null default 0,
    trip_distance    numeric(14,2) not null default 0,
    odometer_reading numeric(14,2) not null default 0,
    fuel_consumption numeric(10,3) not null default 0,
    price_per_liter  numeric(10,3) not null default 0,
    latitude         numeric(10,7),
    longitude        numeric(10,7),
    location_name    text check (length(location_name) <= 200),
    timestamp        bigint not null default 0,
    notes            text check (length(notes) <= 1000),
    trashed_at       bigint,
    deleted_at       timestamptz,
    foreign key (car_id, user_id) references public.cars(id, user_id) on delete cascade,
    -- A refill outlives the trip it was grouped into; losing the grouping is
    -- not a reason to lose the refill.
    foreign key (trip_id, user_id) references public.trips(id, user_id) on delete set null
);

-- ── expenses ─────────────────────────────────────────────────────────────
create table public.expenses (
    id                             uuid primary key default gen_random_uuid(),
    user_id                        uuid not null default auth.uid()
                                       references auth.users(id) on delete cascade,
    car_id                         uuid not null,
    category                       text not null default '' check (length(category) <= 100),
    amount                         numeric(14,2) not null default 0,
    timestamp                      bigint not null default 0,
    notes                          text check (length(notes) <= 1000),
    reminder_date                  bigint,
    reminder_mileage               integer,
    reminder_enabled               boolean not null default true,
    pre_expiry_notification_sent   boolean not null default false,
    reminder_dismissed             boolean not null default false,
    trashed_at                     bigint,
    deleted_at                     timestamptz,
    foreign key (car_id, user_id) references public.cars(id, user_id) on delete cascade
);

-- ── expense_categories ───────────────────────────────────────────────────
-- Keyed by its name rather than by a generated id: two phones that both have a
-- "Πλύσιμο" category mean the same category, and giving each a uuid of its own
-- would quietly produce two.
create table public.expense_categories (
    user_id       uuid not null default auth.uid()
                      references auth.users(id) on delete cascade,
    name          text not null check (length(trim(name)) between 1 and 100),
    is_custom     boolean not null default true,
    is_quick_pick boolean not null default false,
    created_at    bigint not null default 0,
    deleted_at    timestamptz,
    primary key (user_id, name)
);

-- ── indexes ──────────────────────────────────────────────────────────────
-- Every sync reads one user's whole table, so that is the index to have.
create index cars_user_idx          on public.cars(user_id);
create index trips_user_idx         on public.trips(user_id);
create index trips_car_idx          on public.trips(car_id);
create index fuel_refills_user_idx  on public.fuel_refills(user_id);
create index fuel_refills_car_idx   on public.fuel_refills(car_id);
create index fuel_refills_trip_idx  on public.fuel_refills(trip_id);
create index expenses_user_idx      on public.expenses(user_id);
create index expenses_car_idx       on public.expenses(car_id);
